// The weekly query set: the 12 queries whose winners fed the plan, plus his own handle.
// Edit here, not in the HTTP nodes. Budget: 12 x 8 TikToks x $0.0037 + 12 x 5 IG x $0.0026 + 12 x 4 YT x $0.004 = ~$0.70/week.
const queries = ['dermatologist', 'botox', 'morpheus8', 'mohs surgery', 'skin cancer check', 'melasma treatment', 'filler migration', 'sunscreen myth', 'ozempic face', 'exosomes skin', 'nyc dermatologist', 'acne scars treatment'];
const hashtags = queries.map(q => q.replace(/\s+/g, ''));
return [{ json: { queries, hashtags, weekOf: new Date().toISOString().slice(0, 10) } }];

// Same metrics as research/ostad/scripts/normalize.py: views/day and engagement; outlier needs creator medians, so the weekly digest ranks by views/day among videos posted in the last 14 days.
const now = Date.now();
const rows = [];
for (const { json: it } of $input.all()) {
  let r = null;
  if (it.webVideoUrl) r = { platform: 'tiktok', url: it.webVideoUrl, creator: it.authorMeta?.name, posted: it.createTimeISO, views: it.playCount, likes: it.diggCount, comments: it.commentCount, shares: it.shareCount, saves: it.collectCount, caption: it.text, q: it.searchQuery };
  else if (it.shortCode) r = { platform: 'instagram', url: it.url, creator: it.ownerUsername, posted: it.timestamp, views: it.videoPlayCount || it.videoViewCount, likes: it.likesCount, comments: it.commentsCount, shares: 0, saves: 0, caption: it.caption, q: it.inputUrl };
  else if (it.viewCount !== undefined) r = { platform: 'youtube', url: it.url, creator: it.channelName, posted: it.date, views: it.viewCount, likes: it.likes, comments: it.commentsCount, shares: 0, saves: 0, caption: it.title, q: it.input };
  if (!r || !r.views || !r.posted) continue;
  const days = Math.max(1, (now - Date.parse(r.posted)) / 864e5);
  if (days > 14) continue;
  r.views_per_day = Math.round(r.views / days);
  r.engagement_rate = +(((r.likes || 0) + (r.comments || 0) + (r.shares || 0) + (r.saves || 0)) / r.views).toFixed(4);
  r.caption = (r.caption || '').slice(0, 300);
  rows.push(r);
}
const seen = new Set();
const top = rows.sort((a, b) => b.views_per_day - a.views_per_day).filter(r => !seen.has(r.url) && seen.add(r.url)).slice(0, 25);
const weekOf = $('Queries').first().json.weekOf;
const md = [`# Ostad weekly — ${weekOf}`, '', `${rows.length} videos posted in the last 14 days across ${$('Queries').first().json.queries.length} queries. Top 25 by views/day:`, '', '| # | platform | creator | views/day | eng | caption |', '|---|---|---|---|---|---|', ...top.map((r, i) => `| ${i + 1} | ${r.platform} | [@${r.creator}](${r.url}) | ${r.views_per_day} | ${(r.engagement_rate * 100).toFixed(1)}% | ${r.caption.replace(/[|\n]/g, ' ').slice(0, 120)} |`)].join('\n');
return [{ json: { weekOf, count: rows.length, top, md, path: `research/ostad/weekly/${weekOf}.md`, content_b64: Buffer.from(md).toString('base64') } }];
